import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Unleashing Hour-Scale Video Training for Long Video-Language Understanding","description":"","frontmatter":{"title":"Unleashing Hour-Scale Video Training for Long Video-Language Understanding","arxiv":"2506.05332","date":"2025-06-05","authors":"Jingyang Lin, Jialian Wu, Ximeng Sun, Ze Wang, Jiang Liu, Yusheng Su, Xiaodong Yu, Hao Chen, Jiebo Luo, Zicheng Liu, Emad Barsoum","categories":"cs.CL, cs.CV","topics":"长视频理解, 指令数据集, 记忆增强","outline":[2,2]},"headers":[],"relativePath":"papers/2506.05332.md","filePath":"papers/2506.05332.md","lastUpdated":null}'),p={name:"papers/2506.05332.md"};function l(i,s,r,o,c,m){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="unleashing-hour-scale-video-training-for-long-video-language-understanding" tabindex="-1">Unleashing Hour-Scale Video Training for Long Video-Language Understanding <a class="header-anchor" href="#unleashing-hour-scale-video-training-for-long-video-language-understanding" aria-label="Permalink to &quot;Unleashing Hour-Scale Video Training for Long Video-Language Understanding&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.05332" target="_blank" rel="noreferrer">2506.05332</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-05</td></tr><tr><td><strong>作者</strong></td><td>Jingyang Lin, Jialian Wu, Ximeng Sun, Ze Wang, Jiang Liu, Yusheng Su, Xiaodong Yu, Hao Chen, Jiebo Luo, Zicheng Liu, Emad Barsoum</td></tr><tr><td><strong>分类</strong></td><td>cs.CL, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用分层字幕流水线合成 9.7K 小时、3.3M 条 QA 的小时级视频指令数据集 VideoMarathon，再配一个把 1 FPS 全量视频特征存进 memory repository、只让 LLM 处理约 6% &quot;衰减 token&quot;、其余靠 MemAug 交叉注意力召回的 Hour-LLaVA，从而真正在小时级视频上做训练而不只是推理外推。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/e-print/2506.05332</code> 的 LaTeX 源码（<code>content/*.tex</code>、<code>assets/table/*.tex</code>）撰写，正文、全部表格与附录均已核验。论文为 NeurIPS 2025 接收，项目页 <code>videomarathon.github.io</code>。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>长视频理解领域有一个尴尬的错配：评测视频越来越长，训练视频却一直很短。论文的表 <code>tab:dataset_comparison</code> 把这件事摊开——LLaVA-Hound 平均 0.2 分钟、ShareGPT4Video 0.3 分钟、LLaVA-Video-178K 0.6 分钟（时长范围都在 3 分钟以内）；而评测端 LongVideoBench 平均 459 秒、VideoMME 1021 秒、LVBench 4037 秒（约 67 分钟）。也就是说，模型在 30 秒的视频上学，在一小时的视频上考。</p><p>在这种错配下，&quot;长视频能力&quot;实际上是从短视频能力外推出来的，而外推的手段是稀疏采样：均匀取 8 到 256 帧。对 30 秒视频这没问题，对一小时视频这等于把 3600 帧压成 64 帧，信息损失是数量级的。论文的核心主张是这条路走不通，必须真的在小时级视频上训练。</p><p>要真训练就撞上两堵墙。第一堵是数据：小时级的、带良好标注的视频指令数据基本不存在，人工标注成本又高得离谱。第二堵是算力：attention 的平方复杂度让小时级视频的 token 预算直接爆掉。这篇论文两堵墙一起拆，数据侧给出 VideoMarathon，模型侧给出 Hour-LLaVA。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>视频指令数据这条线</strong>的演化路径很清楚：早期用 ASR 字幕（HowTo100M、ACAV100M）绕开人工标注，代价是标签噪声大；中期用模板在已有 caption 数据集上生成 QA（VideoChat）；近期用 GPT-4V/4o 直接产高质量 caption 与 QA（ShareGPT4Video、LLaVA-Video-178K）。质量确实上去了，但视频长度一直没上去，因为长视频的 caption 成本随时长线性涨，而闭源大模型的调用费用把这条路堵死了。</p><p><strong>长视频建模这条线</strong>分成两派，论文把它们的矛盾表述得很干净。压缩派把 token 压小：关键帧选择（LongVU、Koala）、slow-fast 采样、空间池化与 token 合并（LLaVA-Video、Chat-UniVi）、问题引导保留（LongVU、Video-XL）。它们训练便宜，但压缩造成的信息损失是<strong>不可逆</strong>的。扩展派把上下文窗口撑大：LongVA 处理 20 万以上 visual token，LongVILA 用多模态序列并行做到 200 万。它们保住了保真度，代价是训练时间与显存随视频长度<strong>线性增长</strong>。</p><p>论文把这个矛盾称作&quot;根本性两难&quot;，并给出自己的定位：优先算力效率，同时保住高保真上下文。这个定位本身就决定了方法形状——必须把&quot;存&quot;和&quot;算&quot;分开。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是承认长视频 caption 不能用一次调用生成。一小时的视频扔给任何模型，输出的都是一段流水账，既丢细节也丢结构。于是自然想到分层：先切片段写细粒度描述，再聚成事件，再聚成全局叙事。这个层级结构同时解决了成本问题——片段级用便宜的 Qwen2VL-7B，事件级与全局级只处理文本，用 DeepSeek-V3 汇总，全程不需要闭源多模态 API。</p><p>第二步是意识到 QA 的多样性必须由 taxonomy 驱动而不是靠模型自由发挥。作者从已有基准里归纳出 22 个任务、6 个主题（temporality、spatiality、object、action、scene、event），并让片段级 caption 本身就按这六个视角来写。这样生成 QA 时，prompt 里能同时塞进任务定义、对应主题的时序 caption、全局 caption 和来自已有基准的示例。</p><p>第三步是模型侧的关键决断：<strong>&quot;看得到&quot;和&quot;算得起&quot;是两件事</strong>。人的记忆系统就是这么工作的——完整经历被存下来，工作记忆里只保留一小部分，需要时再检索。把这个类比落地，就得到三个组件：存全量的 memory repository、扔掉大部分的 forgetting mechanism、以及把扔掉的东西按需捞回来的 MemAug。</p><p>第四步是发现&quot;捞回来&quot;需要位置对齐。衰减 token 与 memory repository 里的全量 token 必须知道彼此的时空对应关系，否则 cross-attention 就是在一堆无序特征里瞎找。这引出了 1D structured RoPE 的设计。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>长视频建模的两难来自一个隐含前提：送进 LLM 的 token 就是模型能用的全部信息。打破这个前提，把&quot;存储&quot;和&quot;计算&quot;分离——1 FPS 的完整视频特征存在外部仓库里，LLM 只处理约 6% 的衰减 token，缺的部分由一个可学习的 cross-attention 模块按问题相关性从仓库里捞。压缩造成的损失因此不再是不可逆的，而扩展派的线性开销也不必付。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据侧：VideoMarathon</strong>。视频源是五个公开数据集的合并——Panda-70M（占大头）、Ego4D、ActivityNet、YouCook2、MovieChat-1K，并只保留至少含三个不同事件的视频以提高时间复杂度。总计 28K 条视频、约 9.7K 小时、平均 20.9 分钟、时长范围 3–60 分钟。QA 共 3.3M 条，其中开放式 1.73M、多选 1.57M。</p><p>分层字幕流水线三层：片段级用 Qwen2VL-7B 从六个视角（时间性、空间性、物体、动作、场景、总述）写详细描述；事件级先由 DeepSeek-V3 根据按时序排列的片段描述判定事件边界，再把边界内的六视角描述汇总成事件摘要；全局级把带边界的事件摘要再喂给 DeepSeek-V3 生成整片叙事。QA 生成用主题特定 prompt，含任务定义、对应主题的时序 caption、全局 caption 与来自已有基准的示范题。</p><p><strong>模型侧：Hour-LLaVA</strong>。视觉编码用 SigLIP + 两层 GELU MLP 投影，帧按 1 FPS 采样，每帧空间上平均池化到固定的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>。得到的全量视频 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 存入 memory repository。</p><p>Forgetting mechanism 在空间与时间两个维度各做 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/4</span></span></span></span> 压缩，合计 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/16</span></span></span></span>，即扔掉约 94%，剩下的叫衰减 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.073em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.923em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">H</span></span><span style="top:-3.6051em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。空间用随机丢弃，时间用均匀采样（两者都是消融选出来的，见 §7）。为控制极端情况，最多保留 512 帧、最少保留 32 帧——注意这个上下限<strong>只作用于衰减 token</strong>，memory repository 里仍是完整的 1 FPS 内容。</p><p>MemAug 模块由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 个标准 transformer block 组成：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0995em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9495em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">H</span></span><span style="top:-3.2551em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.273em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3567em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord text mtight"><span class="mord mtight">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1433em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2503em;"><span></span></span></span></span></span></span><span class="mopen"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.923em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">H</span></span><span style="top:-3.6051em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">q</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing mult"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.85em;"><span style="top:-2.85em;"><span class="pstrut" style="height:3.2em;"></span><span style="width:0.333em;height:1.2em;"><svg xmlns="http://www.w3.org/2000/svg" width="0.333em" height="1.2em" viewBox="0 0 333 1200"><path d="M145 15 v585 v0 v585 c2.667,10,9.667,15,21,15
c10,0,16.667,-5,20,-15 v-585 v0 v-585 c-2.667,-10,-9.667,-15,-21,-15
c-10,0,-16.667,5,-20,15z M188 15 H145 v585 v0 v585 h43z"></path></svg></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.35em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="delimsizing size1">)</span></span><span class="mord">.</span></span></span></span></span></p><p>cross-attention 里衰减 token 与问题 token 作为 query，从 memory repository（key/value）里检索；self-attention 里问题相关信息从问题 token 流向衰减 token。为了让 query 知道自己在原视频里的位置，先把全量 token 展平成 1D 并施加 structured RoPE，再按时空对齐给衰减 token 构造对应的 1D RoPE。</p><p><strong>训练三阶段</strong>（表 <code>tab:training_config</code>）：图文预训练用 LLaVA-OV 单图子集 3B 样本，只训 MemAug；视频语言适配用 0.6M 样本（0.12M 单图、0.05M 多图、0.09M 文本、0.3M 短视频），全参数训一个 epoch；视频指令微调用 4.4M 样本（1.14M 单图、0.5M 多图、0.81M 文本、1.3M 短视频、0.7M 来自 VideoMarathon 的长视频），冻结视觉编码器。3B 用 64 张 AMD MI250、7B 用 64 张 MI300X，AdamW，学习率 2e-5，warmup 0.03，cosine 退火，batch 128/256。</p><p><strong>一个具体例子</strong>。一段 40 分钟的烹饪视频：1 FPS 得到 2400 帧特征全部入库；forgetting 均匀取 600 帧、每帧随机留 1/4 的 patch，LLM 只看到这些。当问题是&quot;她在放盐之前搅了几次&quot;时，MemAug 用问题 token 作 query 去仓库里检索，把落在放盐前后那段时间里的完整帧特征捞回来注入衰减 token，LLM 因此能在只处理 6% token 的前提下回答一个需要密集时间证据的问题。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化程度不高，唯一值得展开的是压缩比与信息可及性的关系。空间与时间各 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/4</span></span></span></span>，合成压缩比</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">4</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">16</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9444em;vertical-align:-0.1944em;"></span><span class="mord">6.25%</span><span class="mpunct">,</span></span></span></span></span></p><p>即扔掉约 93.75% 的 token。关键在于这个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 只决定 <strong>LLM decoder 的输入长度</strong>，不决定模型可及的信息量：memory repository 保留 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">100%</span></span></span></span>，MemAug 的 cross-attention 在完整的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 上做 key/value。因此计算量是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen"><span class="delimsizing size1">(</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">L</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose"><span class="delimsizing size1">)</span></span></span></span></span> 在 decoder 侧、加上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen"><span class="delimsizing size1">(</span></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal">L</span><span class="mclose"><span class="delimsizing size1">)</span></span></span></span></span> 在 MemAug 的 cross-attention 侧，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 是全量 token 数、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 是 block 数。与扩展派的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 相比，二次项的系数被 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 压掉，而与压缩派相比，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 这个因子仍然出现在 cross-attention 里，也就是<strong>保真度是用 MemAug 的线性项换来的</strong>。论文没有给出这个开销的显式核算，上式是我按其架构描述推出的（属于推断，非论文明确声称）。</p><p>论文实际报告的最强定量关系反而在位置编码上。去掉 1D structured RoPE 后（表 <code>tab:rope</code>），VideoMME 的 temporal reasoning 子集从 46.3 掉到 35.6（−10.7，3B）、从 56.5 掉到 38.4（−12.1，7B）。这意味着 MemAug 的价值不在&quot;能检索&quot;，而在&quot;检索到的东西带着正确的时间坐标&quot;。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>评测四个基准：TempCompass（平均 11 秒）、LongVideoBench（459 秒）、VideoMME（1021 秒）、LVBench（4037 秒）。LVBench 的平均时长已超过训练时的最长 60 分钟，作者把它当作分布外压力测试。</p><p><strong>问题一：整体上打得过谁？</strong> 表 <code>tab:overall_table</code>。3B 档：Hour-LLaVA-3B 在 TempCompass 63.6、LongVideoBench 57.8、VideoMME 60.6/66.7（无字幕/有字幕）、LVBench 44.7；同档次的 LLaVA-Video-3B 分别是 63.4 / 55.2 / 58.7 / 41.7。7B 档：Hour-LLaVA-7B 为 68.1 / 60.4 / 63.6/70.2 / 45.6，LLaVA-Video-7B 为 64.3 / 58.2 / 63.3/69.7 / 42.2。LVBench 上相对次优分别领先 3.0 与 3.4 点，LongVideoBench 上领先 2.6 与 1.9 点。VideoMME 的 Medium 与 Long 两档提升更明显（7B：Medium 63.8 对 58.9，Long 55.0 对 53.0）。</p><p><strong>问题二：长视频数据到底有没有用？</strong> 图 <code>fig:datamix</code> 的混合实验做得很干净：从 VideoMarathon 与 LLaVA-Video-178K 各抽 70K 指令样本 / 10K 视频，规模严格对齐，再各配同样的 60K 多模态样本，只改长短视频比例。Hour-LLaVA-3B 的表现随长视频比例上升而变好，<strong>在长短比 3:1 时达峰</strong>，长视频占满 100% 时反而下降。TempCompass 上加入长视频不明显损害短视频能力。</p><p><strong>问题三：稀疏采样能不能靠加数据补救？</strong> 同一张图里还训了 LLaVA-Video（均匀取 64 帧）。结论是它<strong>完全不从长视频数据里获益，长视频训练后性能甚至下降</strong>。这条对照是全文对&quot;必须真的训长视频&quot;这一主张最直接的支持——数据给了，但架构接不住。</p><p><strong>问题四：forgetting 该怎么做？</strong> 这里有两张值得仔细读的表。空间侧（表 <code>tab:sf_strategy</code>，图文预训练阶段）：base 每图 729 token 时 MMStar 52.8 / ScienceQA 84.7 / RealWorldQA 58.8；随机丢弃到 196 token 后是 51.9 / 84.5 / <strong>59.6</strong>；均匀丢弃是 51.5 / 83.7 / 59.5。<strong>随机剪枝在 RealWorldQA 上甚至超过了不压缩的 base</strong>，且整体只掉不到 1 点。时间侧（表 <code>tab:tf_strategy</code>）：均匀 54.0 / 40.6（LongVideoBench / LVBench）、关键帧 53.5 / 40.3、问题引导 53.4 / 39.7、随机 53.2 / 38.8。<strong>最朴素的均匀采样赢了全部精心设计的选帧方法</strong>，而随机采样落后均匀不到 0.8 与 1.8 点。作者对此的解读是&quot;MemAug 有效到不依赖人工设计的压缩策略&quot;，这个解读合理，但它同时也说明这一层的选择空间本身很窄。</p><p><strong>问题五：MemAug 值多少分？</strong> 表 <code>tab:memaug</code>：在三种压缩策略上分别对比有无 MemAug——均匀 54.0 对 52.1（+1.9）/ 40.6 对 38.3（+2.3）；关键帧 53.5 对 52.0（+1.5）/ 40.3 对 38.9（+1.4）；问题引导 53.4 对 51.0（+2.4）/ 39.7 对 37.5（+2.2）。block 数扫描（表 <code>tab:memaug_num</code>）：1/2/4/8 块在 TempCompass 为 59.4/59.8/59.7/59.2，LongVideoBench 为 53.2/53.5/54.0/53.4，LVBench 为 40.0/40.3/40.6/40.5，默认取 4。</p><p><strong>问题六：memory repository 的规模重要吗？</strong> 图 <code>fig:final</code>（中）显示 LVBench 性能随仓库规模缩小而下降，因此保留完整的 1 FPS。</p><p><strong>数据质量核验</strong>（附录 §human_eval）：人工检查 330 条 QA。多选题 80 条，判定标准是&quot;恰有一个正确选项&quot;，准确率 <strong>78.7%</strong>。开放式 200 条 Yes/No 题测偏置，Pct. Diff 0.04、FP Ratio 0.40。另 50 条由 20 名志愿者按 1–10 打分测幻觉，均分 <strong>7.81 ± 0.59</strong>，得分 ≥7 的占比超过 80%。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：长视频理解的训练与评测存在数量级错配（训练平均 0.6 分钟，LVBench 平均 67 分钟），VideoMarathon 用 Qwen2VL-7B + DeepSeek-V3 的分层字幕流水线把它补上，产出 9.7K 小时、平均 20.9 分钟、3.3M 条 QA。Hour-LLaVA 把存储与计算分开：1 FPS 全量特征入库，LLM 只处理约 6% 的衰减 token，MemAug 用 4 个 transformer block 按问题从库里召回。长短视频 3:1 混合时效果最好，纯长视频反而下降；而稀疏采样的 LLaVA-Video 拿到同样的长视频数据后性能不升反降。消融里最诚实的一条是均匀采样打败了关键帧与问题引导选帧，随机空间剪枝甚至超过了不压缩的 base。MemAug 的增益是 1.4 到 2.4 点，而去掉 1D structured RoPE 会掉 10.7 到 12.1 点，说明真正吃重的是时空位置对齐而非检索本身。</p><p><strong>3 句版</strong>：把小时级视频训练从&quot;没有数据&quot;和&quot;算不动&quot;两侧同时打通，数据侧靠分层字幕合成、模型侧靠存算分离。核心证据是稀疏采样模型在同样的长视频数据上无法获益，而 Hour-LLaVA 可以。但同一批消融也显示，均匀与随机这类平凡策略在这套框架里已经接近最优，方法的增量主要来自 MemAug 的位置对齐机制。</p><p><strong>1 句版</strong>：让 LLM 只看 6% 的 token，但保留 100% 的视频在一个可检索、带时空坐标的外部记忆里，就能在一小时的视频上真正做训练。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>用 Qwen2VL-7B 加 DeepSeek-V3 合成的 3.3M 条 QA，其标签质量足以支撑&quot;数据集高质量&quot;这个结论</strong>。</p><p>论文自己给出的校准数字是：多选题在 <strong>80 条</strong>样本上人工准确率 78.7%。也就是说，按作者自己的判据（恰有一个正确选项、且与视频相关），大约每五条多选训练样本就有一条是坏的，而 VideoMarathon 里多选题有 1.57M 条。开放式那侧，50 条样本由 20 名志愿者打分得到 7.81 ± 0.59，作者用&quot;7.5 分以上算基本正确&quot;作为通过线，均值只比这条线高 0.31，而标准差是 0.59——<strong>通过线落在一个标准差之内</strong>，论文没有报告这个差异的显著性，也没有给 78.7% 的置信区间（80 条样本下，二项分布的 95% 区间大约是 ±9 个百分点）。</p><p>这条假设为什么要命：VideoMarathon 的全部价值主张是&quot;高质量的小时级指令数据&quot;，而模型侧的所有增益都建立在用它训练之上。如果标签噪声率真的接近 20%，那么&quot;3:1 混合最优、100% 长视频反而下降&quot;这个现象就有了一个更平凡的解释——不是长短视频需要平衡，而是<strong>长视频数据的噪声在占比过高时压过了它带来的信号</strong>，短视频数据（人工与 GPT-4o 质量更高）在起降噪作用。论文把这个现象归因于&quot;异质数据源带来的多样性&quot;（原文用了 possibly due to 的措辞，属于作者自己标注的推测），但没有做区分这两种解释的实验：比如按人工评分过滤掉低分样本后重跑混合曲线。这属于缺失证据，且它正好压在数据集的核心卖点上。</p><p>作者在 Limitations 里确实承认了&quot;合成数据不可避免含噪声、当前流水线未显式处理&quot;，这是诚实的；但承认不等于校准，噪声率对下游结论的影响仍未被量化。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 64 卡训练。一周内可做完的最小验证针对上面那条假设：</p><ol><li>从公开的 VideoMarathon 里随机抽 500 条多选 QA（比论文的 80 条大一个量级），按作者的同一判据人工标注，得到准确率与 95% 置信区间。同时按 6 个主题分层统计——时间性与事件类问题依赖跨片段汇总，噪声率应当显著高于物体与场景类。</li><li>用这批标注训练一个轻量的质量判别器（或直接用一个强 VLM 做 LLM-as-judge，但<strong>必须先在这 500 条人工标签上报出它与人的一致率</strong>，否则判别器本身没有校准）。</li><li>用判别器过滤掉预测为坏的样本，构造一个规模更小但更干净的子集，在 Hour-LLaVA-3B 的视频指令微调阶段用两个配置各训一次：全量 70K 长视频样本 对 过滤后的同等<strong>样本数</strong>（而非同等比例，以控制数据量）。</li><li>判据：若过滤子集在 LongVideoBench 与 LVBench 上不劣于全量，说明噪声确实在拖后腿，&quot;3:1 最优&quot;的多样性解释需要修正；若两者持平，则噪声的影响可以忽略，作者的解释站得住。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>第一重攻击：把被移到附录的对手放回主表。</strong> 主表 <code>tab:overall_table</code> 的结论是&quot;在 3B 与 7-8B 两档都取得开源最佳&quot;。但附录表 <code>tab:more_compare</code> 里，LVBench 上 InternVideo2.5-8B 是 46.4，高于 Hour-LLaVA-7B 的 45.6；LongVideoBench 上 InternVideo2.5-8B 是 60.6，高于 60.4；VideoMME（无字幕）上 InternVL3-8B 是 66.3、Qwen2.5-VL-7B 是 63.3，Hour-LLaVA-7B 是 63.6。3B 档同理，Qwen2.5-VL-3B 的 VideoMME 无字幕 61.5 高于 Hour-LLaVA-3B 的 60.6。作者在附录里如实写了&quot;comparable with, and sometimes outperforms&quot;，措辞是准确的，但主表的排版把这些对手排除在外，读者只看主表会得到更强的印象。构造性的攻击就是把两张表合并重排，此时&quot;开源最佳&quot;这个结论会缩水成&quot;在 LLaVA 系基座内最佳&quot;。</p><p><strong>第二重攻击：给出真正的平凡基线并逼问增量。</strong> 论文自己的表 <code>tab:tf_strategy</code> 已经显示，随机时间采样（53.2 / 38.8）与均匀采样（54.0 / 40.6）相差不到 0.8 与 1.8 点，而所有精心设计的选帧方法都夹在中间且不如均匀。表 <code>tab:sf_strategy</code> 更进一步，随机空间剪枝到 1/4 token 在 RealWorldQA 上（59.6）超过了完全不压缩的 base（58.8）。把这两条放在一起，可以构造一个极简对照：<strong>MemAug + 随机时空剪枝</strong>（完全不做任何&quot;聪明&quot;的选择），它在 LongVideoBench 上应当仍有 53 左右。此时 Hour-LLaVA 完整版相对这个极简版的增量只有不到 1 点，而论文全部的 forgetting mechanism 讨论都在这 1 点之内。方法真正的护城河因此收窄到 MemAug 与 1D RoPE 两件事上——后者的消融幅度（−10.7 / −12.1）远大于前者（+1.4 到 +2.4），这提示 MemAug 的贡献可能主要是&quot;给衰减 token 补上正确的时间坐标&quot;，而非&quot;召回了缺失的语义&quot;。一个能分开这两者的实验是：保留 1D structured RoPE，但把 cross-attention 的 key/value 从 memory repository 换成<strong>随机打乱时间顺序的同一批特征</strong>。若性能只轻微下降，则召回的语义内容不重要，位置对齐才是全部。</p><p><strong>第三重攻击：置信区间缺失。</strong> 全文所有表格都是单次运行的点估计，没有任何种子重复或误差棒。MemAug 的 +1.4、block 数扫描里 4 块与 2 块的 0.5 点差距、LongVideoBench 上 1.9 点的领先，都落在同量级基准上常见的种子波动范围内。唯一带正负号的数字是人工评分的 7.81 ± 0.59。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：VideoMarathon 的标注是<strong>开环</strong>的——字幕与 QA 一次性生成，质量只在事后被 330 条人工样本抽检，噪声不进入生成过程。而 §7 里&quot;3:1 混合最优&quot;这个现象暗示，数据的边际价值随占比变化，也就是说不同样本的价值差异很大，但流水线对所有样本一视同仁。</p><p><strong>新的 framing</strong>：把长视频指令数据的构造当作一个<strong>主动学习</strong>问题而不是一次性合成问题。核心观察是，一条 QA 的价值应当由&quot;当前模型答不对它&quot;来定义，而不是由生成它时用了多好的 caption 来定义。具体做法是把生成与训练闭环：先用小规模数据训一个 checkpoint，再用它对候选 QA 打分，把模型已经能答对的样本降权、答错且人工可验证的样本升权，用这个信号反过来指导下一轮该给哪些视频、哪些主题多生成 QA。这会把&quot;9.7K 小时&quot;这个规模指标替换成&quot;有效信息量&quot;指标。</p><p><strong>可借鉴的相邻工具</strong>：一是指令微调里的数据选择方法（LIMA 一类的少而精假设，以及基于梯度影响函数的样本打分）；二是主动学习里的 expected model change / BALD 采集函数；三是弱监督学习里的 Snorkel 式标注函数聚合——把片段级、事件级、全局级三层 caption 当成三个独立的标注函数，用它们之间的一致性来估计每条 QA 的可靠度，这一步完全不需要额外人工。</p><p><strong>第一个实验</strong>：在现有 VideoMarathon 上计算三层 caption 的互相一致性分数（例如用事件级摘要回答由片段级 caption 生成的 QA，看能否答对），把这个分数与 §10 中拿到的 500 条人工标签做相关性分析。若相关性显著，说明层间一致性可以当作免费的噪声估计器；随后用它把 3.3M 条 QA 排序，取前 30% 训练并与全量对比。若前 30% 能达到全量的效果，那么这个领域&quot;数据集越大越好&quot;的默认叙事就该被换成&quot;有效样本密度&quot;的叙事。</p>`,64)])])}const d=a(p,[["render",l]]);export{h as __pageData,d as default};
